## Tests for hexdump.
##
## Run with: nimble test
## (the nimble task compiles with --path:src)
##
## The golden expectations below are not hand-written: they were
## generated by an independent Python reference implementation of the
## xxd layout (scripts/hexdump_reference.py) and pasted in verbatim, so
## a rendering bug in Nim would have to match a bug in a separate
## implementation to slip through.

import std/[unittest, strutils, sequtils]
import hexdump

suite "dumpLines (xxd golden reference)":
  test "default layout, single line":
    let got = dumpLines("Hello, world!")
    check got == @["00000000: 4865 6c6c 6f2c 2077 6f72 6c64 21         Hello, world!"]

  test "two lines across a 16-byte boundary":
    let data = toSeq(0'u8..19'u8).mapIt(chr(it.int)).join()
    let got = dumpLines(data)
    check got == @[
      "00000000: 0001 0203 0405 0607 0809 0a0b 0c0d 0e0f  ................",
      "00000010: 1011 1213                                ....",
    ]

  test "exactly one full line":
    let got = dumpLines("A".repeat(16))
    check got.len == 1
    check got[0] == "00000000: 4141 4141 4141 4141 4141 4141 4141 4141  AAAAAAAAAAAAAAAA"

  test "one byte over the boundary pads the hex area":
    let got = dumpLines("A".repeat(17))
    check got.len == 2
    check got[1] == "00000010: 41                                       A"

  test "unprintable gutter placeholders":
    # NUL, SOH, US (0x1f), DEL (0x7f), 0x80, 0xff are all outside the
    # printable range 0x20..0x7e; the hex column still shows them.
    let got = dumpLines("\x00\x01\x1f\x7f\x80\xff")
    check got == @["00000000: 0001 1f7f 80ff                           ......"]

  test "printable boundaries: space and tilde stay literal":
    let got = dumpLines(" ~")
    check got == @["00000000: 207e                                      ~"]

  test "a lone printable space keeps its gutter slot":
    let one = dumpLines(" ")
    check one == @["00000000: 20                                        "]
    check one[0].endsWith(" ")  # gutter shows the space literally

suite "dumpLines (variants)":
  test "width=8 group=1":
    let got = dumpLines("x".repeat(9), DumpOptions(width: 8, group: 1,
        baseAddr: 0, unprintable: '.'))
    check got == @[
      "00000000: 78 78 78 78 78 78 78 78  xxxxxxxx",
      "00000008: 78                       x",
    ]

  test "baseAddr shifts the address column":
    let got = dumpLines("q".repeat(3), DumpOptions(width: 4, group: 1,
        baseAddr: 0x1000, unprintable: '.'))
    check got == @["00001000: 71 71 71     qqq"]

  test "addresses wider than 32 bits truncate like xxd's %08x":
    let got = dumpLines("hi", DumpOptions(width: 16, group: 2,
        baseAddr: BiggestInt(0xFFFFFFFF'u64 + 5'u64), unprintable: '.'))
    check got[0].startsWith("00000004: ")

  test "empty input produces no lines":
    check dumpLines("").len == 0
    check dump("") == ""

suite "option validation":
  test "impossible layouts raise ValueError":
    expect ValueError:
      discard dumpLines("x", DumpOptions(width: 0, group: 1, baseAddr: 0,
          unprintable: '.'))
    expect ValueError:
      discard dumpLines("x", DumpOptions(width: 16, group: 0, baseAddr: 0,
          unprintable: '.'))
    expect ValueError:
      discard dumpLines("x", DumpOptions(width: 4, group: 8, baseAddr: 0,
          unprintable: '.'))

  test "defaultDumpOptions matches the golden expectations":
    let d = defaultDumpOptions()
    check d.width == 16 and d.group == 2 and d.baseAddr == 0 and
        d.unprintable == '.'

suite "dump (string form)":
  test "joins with newlines and ends with one":
    let got = dump("Hello, world!")
    check got.endsWith("\n")
    check got.count('\n') == 1
    check got == "00000000: 4865 6c6c 6f2c 2077 6f72 6c64 21         Hello, world!\n"

suite "parseDump (round-trip)":
  test "random corpus of 2000 bytes round-trips":
    var state = 0x9E3779B97F4A7C15'u64
    proc nextU64(): uint64 =
      state = state xor (state shl 13)
      state = state xor (state shr 7)
      state = state xor (state shl 17)
    var data = newString(2000)
    for i in 0 ..< 2000:
      data[i] = chr(int(nextU64() and 0xFF'u64))
    check parseDump(dumpLines(data)) == data
    check parseDump(dump(data)) == data

  test "every length from 1 to 40 round-trips":
    let data = toSeq(0'u8..39'u8).mapIt(chr(it.int)).join()
    for n in 1 .. 40:
      let d = data[0 ..< n]
      check parseDump(dumpLines(d)) == d

  test "custom layouts round-trip too":
    let layouts: seq[DumpOptions] = @[
      DumpOptions(width: 8, group: 1, baseAddr: 7, unprintable: '?'),
      DumpOptions(width: 3, group: 3, baseAddr: 0, unprintable: '.'),
      DumpOptions(width: 32, group: 4, baseAddr: 0x10000, unprintable: '.'),
    ]
    for opts in layouts:
      let d = "mixed \x00 content \xff here"
      check parseDump(dumpLines(d, opts)) == d

  test "parseDump degrades gracefully on junk input":
    # blank lines and lines without an address column are skipped;
    # nothing raises, the rest is parsed.
    let good = dumpLines("cat")
    check parseDump(@["", "not a dump line"] & good) == "cat"
    check parseDump(@[]) == ""

suite "utf-8 gutter":
  test "each byte gets one gutter slot, characters never split":
    # é is two bytes (0xc3 0xa9); both get placeholder slots in the
    # gutter, matching xxd's per-byte view.
    let got = dumpLines("é!")
    check got[0].startsWith("00000000: c3a9 21")
    check got[0].endsWith("..!")
